export function chart(el,data,key){if(!data.length){el.innerHTML='<div class="empty">No history yet. Log an exercise to start the trend.</div>';return}let W=720,H=280,p={l:48,r:18,t:22,b:42},v=data.map(x=>x[key]),mx=Math.max(...v,1),mn=Math.min(...v,0),r=mx-mn||1,x=i=>p.l+i/Math.max(data.length-1,1)*(W-p.l-p.r),y=n=>H-p.b-(n-mn)/r*(H-p.t-p.b),path=data.map((d,i)=>(i?'L':'M')+x(i)+' '+y(d[key])).join(' ');let grid='';for(let i=0;i<5;i++){let q=mn+r*i/4,yy=y(q);grid+=`<line x1="${p.l}" x2="${W-p.r}" y1="${yy}" y2="${yy}" class="grid"/><text x="${p.l-8}" y="${yy+3}" text-anchor="end">${Math.round(q).toLocaleString()}</text>`}let dots=data.map((d,i)=>`<circle cx="${x(i)}" cy="${y(d[key])}" r="4" class="dot"><title>${new Date(d.date+'T12:00:00').toLocaleDateString('en',{month:'short',day:'numeric'})} · ${d[key].toFixed?d[key].toFixed(1):d[key]}</title></circle>`).join('');let labels=data.map((d,i)=>(i===0||i===data.length-1||data.length<7)?`<text x="${x(i)}" y="${H-14}" text-anchor="middle">${new Date(d.date+'T12:00:00').toLocaleDateString('en',{month:'short',day:'numeric'})}</text>`:'').join('');el.innerHTML=`<svg viewBox="0 0 ${W} ${H}" class="chart" aria-label="Progress chart">${grid}<path d="${path}" class="line"/>${dots}${labels}</svg>`}
